"""Transparent evidence flags; no arbitrary overall confidence score."""
import os
from pathlib import Path
import pandas as pd,numpy as np,json
R=Path(os.environ.get('TWSA_RESEARCH_ROOT',Path(__file__).resolve().parents[1]));O=R/'Thailand_Direct_WaterGAP_Analysis/robustness_extension';T=O/'tables'
read=lambda n:pd.read_csv(T/n,dtype={'region':str})
p=read('factorial_product_component_support_trends.csv');m=read('alternative_baseline_trends.csv');w=read('fixed_network_comparison.csv');r=read('reservoir_cluster_and_influence.csv');rain=read('rainfall_concentration_mechanism.csv')
rows=[]
for (code,var),g in p[(p.component=='residual_mm')&(p.support=='provider_land')].groupby(['region','variable']):
 z=g.seasonal_sen_mm_year;core=p[(p.region==code)&(p.variable==var)&(p.component=='residual_mm')&(p.support!='provider_land')]
 bm=m[(m.region==code)&(m.component=='residual_mm')&m.baseline.isin(['WaterGAP_GSWP3_ERA5','watergap2-2e_20CRV3_ERA5'])];ww=w[(w.region==code)&(w.variable==var)&(w.panel=='strict_balanced')&(w.component=='residual_mm')];rv=r[r.region==code];rr=rain[(rain.region==code)&(rain.variable==var)&rain.primary_metric&(rain.component=='residual_mm')]
 row={'region':code,'basin':g.basin.iloc[0],'variable':var,'product_component_variants':len(g),'product_component_negative':int((z<0).sum()),'all_tested_product_component_slopes_negative':bool((z<0).all()),'slope_min_mm_year':z.min(),'slope_max_mm_year':z.max(),'interior_variants':len(core),'interior_negative':int((core.seasonal_sen_mm_year<0).sum()),'all_tested_product_OLS_intervals_below_zero':bool((g.OLS_hi95<0).all()),'alternative_TWS_baselines':len(bm) if var=='TWSA' else 0,'alternative_TWS_baselines_negative':int((bm.seasonal_sen_mm_year<0).sum()) if var=='TWSA' else np.nan,'fixed_well_years':ww.n_years.iloc[0] if len(ww) else 0,'fixed_well_groups':ww.station_groups.iloc[0] if len(ww) else 0,'fixed_well_r':ww.r.iloc[0] if len(ww) else np.nan,'fixed_well_interval_excludes_zero':bool(ww.station_boot_lo95.iloc[0]>0 or ww.station_boot_hi95.iloc[0]<0) if len(ww) and np.isfinite(ww.station_boot_lo95.iloc[0]) else False,'reservoir_paired_months':rv.n_months.iloc[0] if len(rv) and var=='TWSA' else 0,'reservoir_adjusted_r':rv.r_season_trend_removed.iloc[0] if len(rv) and var=='TWSA' else np.nan,'reservoir_interval_excludes_zero':bool(rv.year_cluster_lo95.iloc[0]>0 or rv.year_cluster_hi95.iloc[0]<0) if len(rv) and var=='TWSA' else False,'residual_Gini_partial_r':rr.partial_r.iloc[0] if len(rr) else np.nan,'residual_Gini_FDR_q':rr.FDR_q.iloc[0] if len(rr) else np.nan,'residual_Gini_LOYO_gain_mm':rr.LOYO_RMSE_gain_mm.iloc[0] if len(rr) else np.nan,'interpretation':'Support flags describe tested choices; not a human-causation probability. Missing evidence is not evidence of no effect.'}
 rows.append(row)
out=pd.DataFrame(rows);out.to_csv(T/'basin_evidence_matrix.csv',index=False)
roles=[{'reference':'WaterGAP_GSWP3_ERA5','full_TWS_evidence_flag':True,'role':'Primary naturalized baseline','limitation':'nosoc; publisher-provided complete water-storage components; a simulation, not observed climate-only storage','source':'https://doi.org/10.25716/GUDE.1TWP-GNQP'}, {'reference':'watergap2-2e_20CRV3_ERA5','full_TWS_evidence_flag':True,'role':'WaterGAP forcing/experiment sensitivity','limitation':'nowatermgt retains other historical forcings; not an independent hydrological model','source':'https://doi.org/10.48364/ISIMIP.398165.3'}, {'reference':'lpjml5-7-10-fire_20CRV3_ERA5','full_TWS_evidence_flag':False,'role':'Structural diagnostic only','limitation':'Equivalent explicit groundwater-storage accounting not established for this exact v5 TWS file; excluded from full-TWS flags','source':'https://doi.org/10.48364/ISIMIP.398165.3'}, {'reference':'miroc-integ-land_20CRV3_ERA5','full_TWS_evidence_flag':False,'role':'Structural diagnostic only','limitation':'Model includes groundwater processes, but the file lists soil/canopy/snow/river/reservoir storage without a separate groundwater term; equivalent accounting unverified','source':'https://doi.org/10.5194/gmd-13-4713-2020'}]
pd.DataFrame(roles).to_csv(T/'model_reference_eligibility.csv',index=False)
summary={'regions':int(out.region.nunique()),'basins':22,'TWS_all_products_negative':int(out[(out.region.str.len()==2)&(out.region!='TH')&(out.variable=='TWSA')].all_tested_product_component_slopes_negative.sum()),'GWS_all_products_negative':int(out[(out.region.str.len()==2)&(out.region!='TH')&(out.variable=='GWSA')].all_tested_product_component_slopes_negative.sum()),'basin_rain_tests_FDR_q_lt_005':int(((rain.region!='TH')&(rain.FDR_q<.05)).sum()),'national_evidence':out[out.region=='TH'].replace({np.nan:None}).to_dict('records')}
(O/'results_summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');print(json.dumps(summary,indent=2))
